<!doctype html>
<html lang="he" dir="rtl">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#5fa8d3">
  <title>MovieMeet — קובעים סרט יחד</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;600;700&display=swap" rel="stylesheet">
  <link rel="icon" href="favicon.svg" type="image/svg+xml">
  <link rel="stylesheet" href="style.css?v=2">
  <style>:root{--cyan:#E8363F;--cyan-dark:#F28C7A;--cyan-light:#4B1B78;--teal:#B0245F;--pastel-bg:#0F0719;--surface:rgba(42,15,69,.93);--text:#fff5fa;--muted:#e2bdd1;--border:rgba(242,140,122,.32);--good:#f28c7a;--shadow:0 8px 28px rgba(0,0,0,.38);--shadow-md:0 14px 36px rgba(0,0,0,.5)}body{background:#0F0719;color:var(--text)}body:before{content:'';position:fixed;inset:0;z-index:-1;background:linear-gradient(rgba(15,7,25,.78),rgba(15,7,25,.94)),url('https://images.unsplash.com/photo-1780147344709-e6f3a57d65e3?auto=format&fit=crop&w=1800&q=80') center/cover}.site-header{background:rgba(15,7,25,.86)}.secondary,.text-button,.link-back,.vote,.genre-button{background:rgba(42,15,69,.82);color:var(--text)}.form-grid input,.form-grid select{background:rgba(15,7,25,.76);color:var(--text)}#accountArea{display:flex;align-items:center;gap:10px}.city-input{max-width:100%}.field-help{margin:2px 0 0;font-size:13px;color:var(--muted)}.genre-choice{display:grid;gap:8px}.genre-choice>strong{font-size:14px}.genre-buttons{display:flex;flex-wrap:wrap;gap:7px}.genre-button{border:1.5px solid var(--border);border-radius:var(--radius);padding:7px 11px;font:inherit;font-size:14px;cursor:pointer}.genre-button.selected{background:#7A2C9E;border-color:#F28C7A}.genre-button.disliked.selected,.delete-candidate{background:#C8102E!important;border-color:#E8363F!important;color:#fff!important}.cinema-note{margin:0;color:var(--muted);font-size:13px}.event-tabs{display:flex;gap:8px;overflow:auto;padding:4px 0 12px}.event-tab{flex:1;white-space:nowrap}.event-pane.hidden{display:none}.meeting-list{display:grid;gap:10px}.meeting-card{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px;border:1px solid var(--border);border-radius:16px;background:rgba(42,15,69,.8)}.admin-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:16px}.admin-stat{padding:13px 8px;text-align:center;border:1px solid var(--border);border-radius:14px;background:rgba(15,7,25,.45)}.admin-stat strong{display:block;color:#F28C7A;font-size:25px}.admin-stat span{font-size:13px;color:var(--muted)}.score-details{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.score-detail{display:grid;gap:7px;padding:13px;border:1px solid rgba(242,140,122,.42);border-radius:14px;background:transparent}.score-detail strong{color:#fff5fa;font-size:14px}.score-detail span{background:transparent!important;color:#e2bdd1!important;padding:0!important;font-size:13px;line-height:1.45}.availability-people{display:flex;align-items:center;gap:9px}.availability-avatars{display:flex;direction:ltr}.availability-avatar{display:grid;place-items:center;width:29px;height:29px;margin-left:-7px;border:2px solid #2A0F45;border-radius:50%;background:#7A2C9E;color:#fff5fa!important;font-size:11px!important;font-weight:700;line-height:1!important}.availability-avatar:first-child{margin-left:0}.availability-avatar.more{background:#B0245F}.match-label{font-weight:700;color:#F28C7A}@media(max-width:640px){.score-details{grid-template-columns:1fr}}@media(max-width:420px){.admin-stats{gap:6px}.admin-stat{padding:10px 4px}.admin-stat strong{font-size:21px}}</style>
</head>
<body>
  <header class="site-header"><a class="brand" href="index.php">MovieMeet</a><div id="accountArea"></div></header>
  <main id="app" class="app-shell" aria-live="polite"></main>
  <template id="homeTemplate">
    <section class="hero"><p class="eyebrow">קובעים סרט בלי אינסוף הודעות</p><h1>מוצאים ערב שמתאים לכולם.</h1><p>חברים בוחרים עיר, שעות וסגנונות. MovieMeet מדרג את הרעיונות ומאפשר להצביע יחד.</p><button class="primary" data-open="create">יוצרים מפגש חדש</button></section><section id="homeProfile" class="card hidden"><p class="eyebrow">ניהול האתר</p><h2>לוח ניהול</h2><p id="homeProfileText"></p><div id="adminStats" class="admin-stats"></div></section><section id="myMeetingsSection" class="card hidden"><div class="section-heading"><div><p class="eyebrow">ניהול מפגשים</p><h2>כל מפגשי הסרט</h2></div></div><div id="myMeetings" class="meeting-list"></div></section>
    <section class="info-grid"><article><strong>1</strong><h2>שולחים קישור</h2><p>כל חבר משתף מתי נוח לו, מאיפה הוא מגיע ומה הוא אוהב לראות.</p></article><article><strong>2</strong><h2>מקבלים סדר</h2><p>המערכת מאזנת זמינות, סגנונות וזמן נסיעה לכל הקבוצה.</p></article><article><strong>3</strong><h2>מצביעים ומזמינים</h2><p>פותחים את עמוד ההזמנה הרשמי, בודקים מושבים וסוגרים ערב.</p></article></section>
  </template>
  <template id="authTemplate">
    <section class="card auth-card"><button class="link-back" data-open="home">חזרה</button><h1>כניסת מנהל</h1><p>הכניסה מיועדת למנהל האתר בלבד.</p><div class="form-grid"><label>אימייל<input id="authEmail" type="email" autocomplete="email" required></label><label>סיסמה<input id="authPassword" type="password" minlength="8" autocomplete="current-password" required></label></div><p id="authError" class="form-error hidden"></p><button id="authSubmit" class="primary">כניסת מנהל</button></section>
  </template>
  <template id="createTemplate">
    <section class="card"><button class="link-back" data-open="home">חזרה</button><h1>מפגש סרט חדש</h1><p>המארגן מוסיף מועמדים אחרי שהחברים מצטרפים.</p><form id="createForm" class="form-grid"><label>שם המפגש<input name="name" maxlength="120" placeholder="למשל: ערב סרט של החבורה" required></label><label>מתאריך<input name="date_start" type="date" required></label><label>עד תאריך<input name="date_end" type="date" required></label><button class="primary">יוצרים קישור למפגש</button></form><p id="createError" class="form-error hidden"></p></section>
  </template>
  <template id="eventTemplate">
    <section class="event-head"><p class="eyebrow">מפגש סרט</p><h1 id="eventName"></h1><p id="eventDates"></p><button id="copyLink" class="secondary">העתקת קישור לחברים</button></section><nav class="event-tabs" aria-label="ניווט מפגש"><button class="secondary event-tab active" data-event-view="suggestions">הצעות</button><button class="secondary event-tab" data-event-view="preferences">העדפות</button><button class="secondary event-tab" data-event-view="people">חברים</button></nav>
    <section id="joinCard" class="card event-pane" data-pane="preferences"><h2>הזמינות שלי</h2><p id="joinComplete" class="field-help hidden"></p><form id="joinForm" class="form-grid"><label>שם<input name="name" maxlength="80" required aria-describedby="nameLockHint"></label><p id="nameLockHint" class="field-help hidden">השם נשמר למענה הזה ואי אפשר לשנות אותו.</p><label>עיר מוצא<input class="city-input" name="city" list="israelCities" autocomplete="address-level2" placeholder="התחילו להקליד עיר או יישוב" required></label><datalist id="israelCities"></datalist><div class="genre-choice"><strong>סגנונות אהובים</strong><div id="likedGenres" class="genre-buttons"></div><input name="genres" type="hidden"></div><div class="genre-choice"><strong>סגנונות שלא אוהבים</strong><div id="dislikedGenres" class="genre-buttons"></div><input name="disliked_genres" type="hidden"></div><div class="availability"><div class="row-title"><strong>חלונות זמן</strong><button id="addWindow" class="text-button" type="button">+ הוספת חלון</button></div><div id="windows"></div></div><button class="primary">שמירת הזמינות</button></form><p id="joinError" class="form-error hidden"></p></section>
    <section id="organizerCard" class="card hidden event-pane" data-pane="suggestions"><h2>הוספת הקרנה</h2><p>מוסיפים רעיון שמצאת באתר הקולנוע הרשמי. בהמשך יתאפשר איסוף שעות אוטומטי.</p><form id="candidateForm" class="form-grid"><label>קולנוע<select name="cinema_id" id="cinemaSelect" required></select></label><p id="cinemaNote" class="cinema-note"></p><label>שם הסרט<input name="movie_title" maxlength="180" required></label><label>סגנונות הסרט<input name="genres" maxlength="160" placeholder="למשל: קומדיה, דרמה"></label><label>תאריך<input name="show_date" type="date" required></label><label>שעה<select name="show_time" id="showTime" required></select></label><button class="primary">הוספת רעיון לדירוג</button></form><p id="candidateError" class="form-error hidden"></p></section>
    <section id="suggestionsSection" class="event-pane" data-pane="suggestions"><div class="section-heading"><div><p class="eyebrow">הצעות מדורגות</p><h2>מה הכי מתאים לכולם?</h2></div><span id="participantCount" class="pill"></span></div><div id="recommendations" class="recommendations"></div></section>
    <section id="peopleSection" class="card event-pane" data-pane="people"><h2>מי כבר מילא?</h2><ul id="participantList" class="participant-list"></ul></section>
  </template>
  <script src="app.js?v=18"></script>
</body>
</html>
